import { Link, useNavigate } from "react-router-dom";
import { Package, UserPlus } from "lucide-react";
import { useTheme } from "./ThemeContext";
import { h } from "./h";
import { Button, GlassPanel, LogoMark, RefImage, ThemeToggleButton } from "./ui";

export function LandingPage() {
  const nav = useNavigate();
  const { dark, toggle } = useTheme();

  return h("div", { className: "relative min-h-screen overflow-hidden" }, [
    h(RefImage, {
      key: "bg",
      n: 12,
      alt: "",
      className: "pointer-events-none absolute inset-0 h-full w-full object-cover opacity-35 dark:opacity-25"
    }),
    h("div", {
      key: "overlay",
      className:
        "absolute inset-0 bg-gradient-to-b from-slate-100/92 via-slate-100/85 to-slate-200/90 dark:from-night-950/95 dark:via-night-950/90 dark:to-slate-950/95"
    }),
    h("div", { key: "content", className: "relative z-10 mx-auto flex min-h-screen max-w-3xl flex-col px-4 py-8 sm:px-6" }, [
      h("div", { key: "top", className: "mb-8 flex items-center justify-between" }, [
        h("div", { key: "brand", className: "flex items-center gap-2" }, [
          h(LogoMark, { key: "lm", className: "h-10 w-10" }),
          h("span", { key: "nm", className: "font-display text-xl font-bold text-slate-900 dark:text-white sm:text-2xl" }, "Campus Mart")
        ]),
        h(ThemeToggleButton, { key: "th", dark, onToggle: toggle })
      ]),
      h(GlassPanel, { key: "hero", className: "text-center sm:text-left" }, [
        h(
          "h1",
          {
            key: "h1",
            className: "font-display text-3xl font-bold leading-tight text-slate-900 dark:text-white sm:text-4xl"
          },
          "Your campus store"
        ),
        h(
          "p",
          {
            key: "sub",
            className: "mx-auto mt-3 max-w-xl text-sm text-slate-600 dark:text-slate-300 sm:mx-0 sm:text-base"
          },
          "Browse electronics, books, clothing, food, and more as a guest. When you are ready to buy, sign in to checkout."
        ),
        h(
          "div",
          {
            key: "cta",
            className: "mt-8 flex flex-col items-stretch justify-center gap-3 sm:flex-row sm:flex-wrap sm:justify-start"
          },
          [
            h(
              Button,
              {
                key: "browse",
                className: "w-full sm:w-auto sm:!min-w-[200px]",
                type: "button",
                onClick: () => nav("/shop")
              },
              [h(Package, { key: "i", className: "h-4 w-4" }), h("span", { key: "t" }, "Browse as guest")]
            ),
            h(
              Button,
              {
                key: "login",
                variant: "ghost",
                className: "w-full border border-slate-300/80 sm:w-auto sm:!min-w-[160px] dark:border-white/15",
                type: "button",
                onClick: () => nav("/login")
              },
              "Sign in"
            ),
            h(
              Button,
              {
                key: "reg",
                variant: "ghost",
                className: "w-full border border-slate-300/80 sm:w-auto sm:!min-w-[160px] dark:border-white/15",
                type: "button",
                onClick: () => nav("/register")
              },
              [h(UserPlus, { key: "i", className: "h-4 w-4" }), h("span", { key: "t" }, "Create account")]
            )
          ]
        ),
        h("p", { key: "vendor", className: "mt-8 text-center text-xs text-slate-500 dark:text-slate-400 sm:text-left" }, [
          "Selling on campus? ",
          h(
            Link,
            {
              key: "vlink",
              to: "/login",
              state: { from: "vendor" },
              className: "font-semibold text-sky-600 hover:underline dark:text-sky-300"
            },
            "Vendor sign in"
          )
        ])
      ]),
      h(
        "p",
        { key: "foot", className: "mt-auto pt-10 text-center text-xs text-slate-500 dark:text-slate-500" },
        "Guests can explore the shop; purchasing requires an account."
      )
    ])
  ]);
}
